export class Pad {
 constructor(context){this.context=context;this.settings=JSON.parse(localStorage.getItem('pad')||'{"note":0,"minor":false,"volume":0.25}');this.playing=false;this.starting=false;this.token=0;this.voices=[];}
 static sounds={Warm:{label:"Warm · suave",harmonics:[0,1,.22,.08],cutoff:1500},Air:{label:"Air · ambiente",harmonics:[0,1,.06,.18,0,.08],cutoff:900},Strings:{label:"Strings · cordas",harmonics:[0,1,.4,.22,.12,.07],cutoff:2400},Organ:{label:"Organ · órgão",harmonics:[0,1,.35,0,.2,0,.1],cutoff:3200}};
 save(){localStorage.setItem('pad',JSON.stringify(this.settings));}
 configure(settings){Object.assign(this.settings,settings);this.save();if(this.playing)this.tune();}
 tune(){const c=this.ctx,p=this.settings,notes=[48+p.note,48+p.note+(p.minor?3:4),48+p.note+7];for(let i=0;i<this.voices.length;i++)this.voices[i].frequency.setTargetAtTime(440*2**((notes[Math.floor(i/3)]-69+(i%3-1)*.065)/12),c.currentTime,.06);const preset=Pad.sounds[p.sound]||Pad.sounds.Warm;this.filter.frequency.setTargetAtTime(preset.cutoff,c.currentTime,.1);if(this.activePreset!==preset){const wave=c.createPeriodicWave(new Float32Array(preset.harmonics.length),new Float32Array(preset.harmonics));for(const v of this.voices)v.setPeriodicWave(wave);this.activePreset=preset;}this.gain.gain.setTargetAtTime(p.volume*.32,c.currentTime,.08);}
 async play(){if(this.playing||this.starting)return;this.starting=true;const token=++this.token;let c;try{c=this.ctx=await this.context();await c.resume();}finally{this.starting=false;}if(token!==this.token)return;this.playing=true;this.activePreset=null;this.gain=c.createGain();this.gain.gain.value=0;const filter=this.filter=c.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1500;filter.Q.value=.5;this.limiter=c.createDynamicsCompressor();this.limiter.threshold.value=-1;this.limiter.knee.value=0;this.limiter.ratio.value=20;this.limiter.attack.value=.002;this.limiter.release.value=.1;this.ceiling=c.createWaveShaper();this.ceiling.curve=Float32Array.from({length:4097},(_,i)=>.65*Math.tanh((i/2048-1)/.65));filter.connect(this.gain).connect(this.ceiling).connect(this.limiter).connect(c.destination);const real=new Float32Array(4),imag=new Float32Array([0,1,.22,.08]),wave=c.createPeriodicWave(real,imag);this.voices=[];this.pans=[];for(let i=0;i<9;i++){const o=c.createOscillator(),pan=c.createStereoPanner();o.setPeriodicWave(wave);pan.pan.value=(i%3-1)*.45;o.connect(pan).connect(filter);o.start();this.voices.push(o);this.pans.push(pan);}this.tune();}
 stop(){this.token++;if(!this.playing)return;this.playing=false;const c=this.ctx,voices=this.voices,pans=this.pans,gain=this.gain,filter=this.filter,limiter=this.limiter,ceiling=this.ceiling;gain.gain.setTargetAtTime(0,c.currentTime,.04);for(const o of voices)o.stop(c.currentTime+.3);setTimeout(()=>{for(const o of voices)o.disconnect();for(const p of pans)p.disconnect();filter.disconnect();gain.disconnect();ceiling.disconnect();limiter.disconnect();},400);this.voices=[];}
}
